function forecastSamples(step=60){
 const out=[],lo=dayStart(),hi=dayEnd(),start=Math.ceil(lo/step)*step;
 for(let m=start;m<=hi;m+=step){
  const sim={now:mh(m),contexts:[...(data.state.contexts||[])],horizon:data.state.horizon};
  const candidates=data.tasks.filter(t=>t.status!=='done').map(t=>opportunityAt(t,sim)).filter(t=>t.bucket!=='MISSED').sort((a,b)=>b.score-a.score||a.cost-b.cost);
  const top=candidates[0]||null,cheap=candidates.filter(t=>t.inWindow&&t.cost<=18).length,soon=candidates.filter(t=>['NOW','SOON'].includes(t.bucket)).length;
  out.push({m,now:mh(m),top,cheap,soon,sim});
 }
 return out;
}
