function routeMetrics(ids=data.state.route,startNow=hm(data.state.now)){
 const gap=nextHardAnchor(startNow),available=gap.kind==='open'?Math.max(0,dayEnd()-startNow):gap.minutes;
 let cursor=startNow,switches=0,deadlineRisk=0,prev=null,used=0;const legs=[];
 for(const id of ids){const t=taskById(id);if(!t)continue;const dur=+t.duration||15;if(prev&&sharedContexts(prev,t).length===0)switches++;cursor+=dur;used+=dur;const late=cursor>hm(t.latest);if(late)deadlineRisk++;legs.push({id,title:t.title,end:cursor,late,shared:prev?sharedContexts(prev,t):[]});prev=t}
 const slack=available-used;return{gap,available,used,slack,fit:slack>=0&&gap.kind!=='inside',switches,deadlineRisk,legs};
}
function proposeGapPack(){
 const cap=Math.max(0,3-data.state.route.length);if(cap<=0){toast('RUN full: 3/3');return}
 const now=hm(data.state.now),gap=nextHardAnchor(now),available=gap.kind==='open'?Math.max(0,dayEnd()-now):gap.minutes;if(available<=0){toast('No free gap before hard anchor');return}
 let remain=available;const picked=[],act=active();
 const candidates=data.tasks.filter(t=>t.status!=='done'&&!data.state.route.includes(t.id)).map(t=>opportunity(t)).filter(t=>!['MISSED','BLOCKED'].includes(t.bucket)&&hm(t.earliest)<=now+available&&(+t.duration||15)<=available).sort((a,b)=>{const aa=(a.hits?.length||0)*7+a.score,bb=(b.hits?.length||0)*7+b.score;return bb-aa||a.cost-b.cost});
 for(const t of candidates){if(picked.length>=cap)break;const dur=+t.duration||15;if(dur<=remain){picked.push(t.id);remain-=dur}}
 ui.previewBundle=picked;render();toast(picked.length?`Previewed ${picked.length} task pack · ${available-remain}/${available}m`:'No coherent pack found');
}
function stressPreview(minutes=30){const now=clamp(hm(data.state.now)+minutes,dayStart(),dayEnd());ui.scenario={now:mh(now),contexts:[...(data.state.contexts||[])],horizon:data.state.horizon};render();toast(`Stress preview +${minutes}m · canon unchanged`)}
function stressSummary(minutes=30){
 const sim={now:mh(clamp(hm(data.state.now)+minutes,dayStart(),dayEnd())),contexts:[...(data.state.contexts||[])],horizon:data.state.horizon};
 const current=data.tasks.filter(t=>t.status!=='done').map(t=>opportunity(t)),future=data.tasks.filter(t=>t.status!=='done').map(t=>opportunityAt(t,sim));
 const map=new Map(current.map(t=>[t.id,t]));const newlyMissed=future.filter(t=>t.bucket==='MISSED'&&map.get(t.id)?.bucket!=='MISSED');const worsened=future.filter(t=>{const c=map.get(t.id);return c&&t.cost-c.cost>=20&&t.bucket!=='MISSED'});
 const route=routeMetrics(data.state.route,hm(sim.now));return{sim,newlyMissed,worsened,route};
}
