function checksum(){let h=2166136261,s=JSON.stringify({tasks:data.tasks,anchors:data.anchors,state:data.state});for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return(h>>>0).toString(16).padStart(8,'0')}
