window.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]'))return;const now=hm(data.state.now);if(e.key==='['){checkpoint('TIME');data.state.now=mh(clamp(now-15,dayStart(),dayEnd()));event('TIME','',data.state.now);render()}else if(e.key===']'){checkpoint('TIME');data.state.now=mh(clamp(now+15,dayStart(),dayEnd()));event('TIME','',data.state.now);render()}else if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();const a=ordered();if(!a.length)return;let i=Math.max(0,a.findIndex(t=>t.id===data.state.selected));i=(i+(e.key==='ArrowDown'?1:-1)+a.length)%a.length;data.state.selected=a[i].id;ui.previewBundle=[];ui.focusChanges++;event('FOCUS',a[i].id,'keyboard');render()}else if(e.key==='Enter'&&data.state.selected)openTask(data.state.selected);else if(e.key.toLowerCase()==='c'&&data.state.selected)routeToggle(data.state.selected);else if(e.key.toLowerCase()==='p')previewBundle();else if(e.key.toLowerCase()==='x')actPreview();else if(e.key.toLowerCase()==='f'){checkpoint('LENS');data.state.lens=data.state.lens==='atlas'?'focus':'atlas';event('LENS','',data.state.lens);render()}else if(e.key.toLowerCase()==='s'){const seq=['auto','districts','parcels'],i=seq.indexOf(ui.semanticScale);ui.semanticScale=seq[(i+1)%seq.length];ui.district=null;render()}else if(e.key.toLowerCase()==='q')openScenario();else if(e.key.toLowerCase()==='g')proposeGapPack();else if(e.key.toLowerCase()==='d')stressPreview(30);else if(e.key.toLowerCase()==='v')setProjection(ui.projection==='atlas'?'plain':'atlas');else if(e.key.toLowerCase()==='u')undo();else if(e.key.toLowerCase()==='n')newTask();else if(e.key.toLowerCase()==='a')newAnchor()});
